const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function renderAssignments(root,{api,token,record,stale,done}){
 const c=record.contract;let data,groups;
 try{[data,groups]=await Promise.all([api.licenseAssignment(token,c.id),api.directoryGroups(token)]);}catch(_){if(!stale())root.textContent='Hub group assignments could not be loaded.';return;}
 if(stale())return;data=data[0];if(!data)return;
 root.innerHTML='<h3>Assign Hub groups</h3><p class="kv">Membership follows the Hub directory. People in several selected groups count once. Assigning a license does not grant access to this contract.</p>'+(!record.canEdit?'<p>'+data.groups.map(esc).join(', ')+'</p>':'<form><label>Assigned groups<select name="groups" multiple size="5">'+groups.map(g=>'<option value="'+esc(g.name)+'" '+(data.groups.includes(g.name)?'selected':'')+'>'+esc(g.name)+' ('+g.members+')</option>').join('')+'</select></label><div class="btnrow"><button class="pill primary" type="submit">Save groups</button></div><p role="status"></p></form>')+'<details><summary>'+data.people.length+' assigned people</summary><div class="chips">'+data.people.map(p=>'<span class="chip">'+esc(p.name)+(p.direct?'':' · via group')+(!p.active?' · inactive':'')+'</span>').join('')+'</div></details>';
 const form=root.querySelector('form');if(!form)return;let busy=false;form.onsubmit=async e=>{e.preventDefault();if(busy||stale())return;busy=true;const b=form.querySelector('button'),out=form.querySelector('[role=status]');b.disabled=true;out.textContent='Saving group assignments…';try{const selected=[...form.elements.groups.selectedOptions].map(o=>o.value);const r=await api.setLicenseAssignments(token,c.id,c.revision,c.holders,selected);if(stale())return;if(r.ok)await done();else out.textContent=r.detail;}catch(_){if(!stale())out.textContent='The save could not be confirmed. Reload before retrying.';}finally{busy=false;if(!stale())b.disabled=false;}};
}
